/* Fictional role briefs. Institutional distinctions are explained in Sources. */
const Roles=(()=>{
 const all=[
  {id:'k',name:'Kitala',type:'Member State delegate',tag:'Equity & access',color:'#dd9d60',priority:'Secure an allocation based on health need, with financing to make access feasible.',constraint:'At least 30% of the pool and at least 25m credits in donor support. Your cabinet accepts transparent reporting.',evidence:'Planning brief: 40m courses of priority need; 20m domestic implementation credits. Both are fictional scenario inputs, not epidemiological estimates.',power:'Propose an allocation and accept or object to the final text. You cannot commit another country’s money.',trade:'Offer accountability in exchange for financing; compare a 35% compromise with a 50% opening demand.',task:'Present the access case and decide whether to back the revised allocation.',line:'Our allocation must respond to need, and financing must make that promise deliverable.'},
  {id:'n',name:'Nordland',type:'Member State delegate',tag:'Finance & accountability',color:'#80aeb9',priority:'Fund a credible collective response that your parliament can defend.',constraint:'At least 15% of the pool; quarterly public reporting; donor financing no greater than 45m credits.',evidence:'Treasury brief: a 45m-credit negotiating ceiling. A 35m package is within mandate. Public reporting is a parliamentary condition in this scenario.',power:'Negotiate financing and accountability, then support or object. Funding does not give you extra votes.',trade:'Offer predictable funding in exchange for reporting. Consider delivery support as part of the same donor envelope.',task:'Defend the reporting clause and assess whether the financing package stays within your mandate.',line:'We can fund solidarity when the text provides clear public accountability.'},
  {id:'m',name:'Meridia',type:'Member State delegate',tag:'Production & certainty',color:'#aba0ca',priority:'Keep production commitments viable while protecting domestic access.',constraint:'A production purchase guarantee and at least 25% of the pool. If a supply disruption occurs, your cabinet’s minimum rises to 30%.',evidence:'Manufacturing brief: firms require purchase certainty. The scenario’s supply update may reduce the common pool from 100m to 80m courses.',power:'Negotiate production terms and your allocation, then support or object. You cannot change the common supply figure.',trade:'Support equitable access in return for a purchase guarantee and a defensible allocation.',task:'Explain the guarantee requirement and revisit your mandate after the supply update.',line:'Production commitments need purchase certainty and a defensible allocation.'},
  {id:'p',name:'Pelagia',type:'Member State delegate',tag:'Delivery & resilience',color:'#9bbf8d',priority:'Make access practical for remote communities, beyond shipments arriving at a port.',constraint:'At least 15% of the pool and at least 10m credits reserved for delivery support.',evidence:'Logistics brief: dispersed island communities require transport and cold-chain support. The 10m threshold is an authored teaching assumption.',power:'Propose a delivery earmark, then support or object. Allocation alone does not establish delivery capacity.',trade:'Back the collective package if delivery support is protected within the donor commitment.',task:'Make the delivery case and check that the final text includes the earmark.',line:'Doses at the port are not access. Delivery must be part of the agreement.'},
  {id:'chair',name:'Assembly Chair',type:'Presiding officer',tag:'Procedure & consensus',color:'#d8c18e',priority:'Give delegations a fair hearing, clarify the draft and establish whether an objection remains.',constraint:'Remain procedurally impartial. In this exercise, you have no separate national allocation or additional vote.',evidence:'Procedure brief: the exercise uses a simplified no-objection consensus check. Real Assembly procedures also provide voting and further committee/plenary stages.',power:'Open the meeting, recognize speakers, invite revisions and announce the recorded result. You cannot manufacture consent or change national mandates.',trade:'Use neutral summaries and return unresolved issues to consultation; do not trade away a delegation’s position.',task:'Manage speaking turns, invite the final position check and explain why the text is or is not adopted.',line:'I invite each delegation to state whether an objection remains to the revised text.'}
 ];
 function validate(mode,assignments){const n=assignments.length;return (mode==='solo'?n===1:n>=2&&n<=5)&&assignments.every(a=>all.some(r=>r.id===a.role))&&new Set(assignments.map(a=>a.role)).size===n;}
 return {all,get:id=>all.find(r=>r.id===id),validate};
})();
if(typeof module!=='undefined')module.exports=Roles;
